is:unread, newer_than:7d, in:inbox.`, 'string') }}

parameters.message:
={{
(() => {
  const escapeMarkdown = (value) => String(value ?? '')
    .replaceAll('\\', '\\\\')
    .replaceAll('_', '\\_')
    .replaceAll('*', '\\*')
    .replaceAll('[', '\\[')
    .replaceAll(']', '\\]')
    .replaceAll(String.fromCharCode(96), '\\' + String.fromCharCode(96));

  const toolName = escapeMarkdown($tool.name);
  const parameters = escapeMarkdown(JSON.stringify($tool.parameters ?? {}, null, 2));

  return '📅 Termin ändern – Freigabe\n\n' +
    'Werkzeug: ' + toolName + '\n\n' +
    'Angaben:\n' + parameters + '\n\n' +
    'Änderung freigeben?';
})()
}}

